import React, { useEffect, useRef, useState, TouchEvent } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";

interface ShowcaseCarouselProps {
  images: {
    src: string;
    alt?: string;
    title?: string;
    description?: string;
  }[];
  interval?: number;
}

const ShowcaseCarousel: React.FC<ShowcaseCarouselProps> = ({
  images,
  interval = 3000,
}) => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const total = images.length;
  const centerImgRef = useRef<HTMLImageElement>(null);
  const touchStartX = useRef<number | null>(null);
  const BASE_WIDTH = 350;
  const BASE_HEIGHT = 500;

  const goNext = () => setActiveIndex((prev) => (prev + 1) % total);
  const goPrev = () => setActiveIndex((prev) => (prev - 1 + total) % total);
  const getRelativeIndex = (index: number) => {
    let offset = index - activeIndex;
    if (offset > total / 2) offset -= total;
    if (offset < -total / 2) offset += total;
    return offset;
  };

  useEffect(() => {
    if (isPaused) return;
    const timer = setInterval(goNext, interval);
    return () => clearInterval(timer);
  }, [isPaused, activeIndex, interval]);

  const handleTouchStart = (e: TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = (e: TouchEvent) => {
    if (touchStartX.current === null) return;
    const deltaX = e.changedTouches[0].clientX - touchStartX.current;
    if (Math.abs(deltaX) > 50) {
      deltaX > 0 ? goPrev() : goNext();
    }
    touchStartX.current = null;
  };

  return (
    <div
      className="relative w-full flex flex-col items-center overflow-hidden py-4"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      {/* Flechas */}
      <button
        onClick={goPrev}
        className="absolute left-2 top-1/2 -translate-y-1/2 z-40 bg-black/50 text-white rounded-full p-2 hover:bg-black transition"
        aria-label="Previous"
      >
        <ChevronLeft size={24} />
      </button>
      <button
        onClick={goNext}
        className="absolute right-2 top-1/2 -translate-y-1/2 z-40 bg-black/50 text-white rounded-full p-2 hover:bg-black transition"
        aria-label="Next"
      >
        <ChevronRight size={24} />
      </button>

      {/* Carrusel */}
      <div className="relative w-full flex justify-center items-center h-[500px]">
        {images.map((img, index) => {
          const offset = getRelativeIndex(index);

          if (Math.abs(offset) > 4) return null;

          const level = Math.abs(offset);
          const z = 30 - level * 10;
          const scale = 1 - level * 0.1;
          const opacity = 1 - level * 0.2;
          const shift = offset * 100;
          const width = BASE_WIDTH;
          const height = BASE_HEIGHT;

          return (
            <img
              key={index}
              ref={offset === 0 ? centerImgRef : null}
              src={img.src}
              alt={img.alt || `Image ${index}`}
              className="absolute rounded shadow-md object-contain transition-all duration-700 ease-in-out bg-black/60"
              style={{
                zIndex: z,
                width: `${BASE_WIDTH}px`,
                height: `${BASE_HEIGHT}px`,
                transform: `translateX(${shift}px) scale(${scale})`,
                opacity: opacity,
              }}
            />
          );
        })}

        {/* Texto */}
        {images[activeIndex]?.title && (
          <div className="absolute bottom-0 sm:bottom-2 left-1/2 -translate-x-1/2 z-40 text-white text-shadow text-center px-4 transition-all duration-500 w-full">
            <h2 className="text-xl sm:text-2xl font-bold drop-shadow">
              {images[activeIndex].title}
            </h2>
            {images[activeIndex].description && (
              <p className="text-sm sm:text-base mt-1 drop-shadow">
                {images[activeIndex].description}
              </p>
            )}
          </div>
        )}
      </div>

      {/* Dots */}
      <div className="flex gap-2 mt-4 z-30">
        {images.map((_, index) => (
          <button
            key={index}
            onClick={() => setActiveIndex(index)}
            className={`w-3 h-3 rounded-full transition ${
              index === activeIndex ? "bg-black" : "bg-gray-400"
            }`}
          />
        ))}
      </div>
    </div>
  );
};

export default ShowcaseCarousel;
